const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa
const sceneDur = 4; // duração da cena em s (troque pela real)

// el = camada de grain (imagem de ruído maior que o quadro, mix-blend-mode: overlay)
const fps = 12, r = rng(99);
tl.set(el, { opacity: 0.08 }, t);
for (let k = 0; k < sceneDur * fps; k++) tl.set(el, { x: (r() - 0.5) * 80, y: (r() - 0.5) * 80 }, t + k / fps);

// items = [líder, eco1, eco2, eco3]; ecos com opacity 0.4 / 0.25 / 0.12
const echoes = items.slice(1);
tl.set(echoes, { opacity: (i) => [0.4, 0.25, 0.12][i] }, t);
items.forEach((node, i) => tl.fromTo(node, { x: 0 }, { x: 600, duration: 0.5, ease: "power3.out" }, t + i * 0.03));
tl.fromTo(echoes, { opacity: (i) => [0.4, 0.25, 0.12][i] }, { opacity: 0, duration: 0.15, immediateRender: false }, t + 0.6);

const sceneDur = 4; // duração da cena em s (troque pela real)

// el = <feTurbulence> do filtro aplicado ao desenho (feDisplacementMap scale="3")
for (let k = 0; k < sceneDur * 12; k++) tl.set(el, { attr: { seed: (k % 3) + 1 } }, t + k / 12);

// global
tl.fromTo(el, { filter: "grayscale(1) contrast(1.1)" }, { filter: "grayscale(0) contrast(1)", duration: 0.8, ease: "power2.inOut" }, t);
// variante local: items[0] = cópia colorida por cima da versão PB
// tl.fromTo(items[0], { clipPath: "circle(0% at 50% 40%)" }, { clipPath: "circle(120% at 50% 40%)", duration: 0.8, ease: "power2.inOut" }, t);

// liga: linha horizontal estourada que abre até a tela inteira
tl.fromTo(el, { scaleX: 0.02, scaleY: 0.004, filter: "brightness(6)" }, { scaleX: 1, duration: 0.18, ease: "power2.out" }, t);
tl.fromTo(el, { scaleY: 0.004, filter: "brightness(6)" }, { scaleY: 1, filter: "brightness(1)", duration: 0.25, ease: "power3.out", immediateRender: false }, t + 0.18);

const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa

// items = blocos da imagem (clones recortados por clip-path)
const r = rng(13);
for (let k = 0; k < 8; k++) items.forEach((b) => tl.set(b, { x: (r() - 0.5) * 120 * (k / 8), scaleY: 1 + r() * 0.6, filter: `hue-rotate(${Math.round(r() * 90)}deg)` }, t + k * 0.06));
tl.set(items, { x: 0, scaleY: 1, filter: "none" }, t + 0.5);

// items = [foto, camada de tinta com gradiente das 2 cores e mix-blend-mode: color]
const [photo, tint] = items;
tl.fromTo(photo, { filter: "grayscale(0) contrast(1)" }, { filter: "grayscale(1) contrast(1.2)", duration: 0.6, ease: "power2.inOut" }, t);
tl.fromTo(tint, { opacity: 0 }, { opacity: 1, duration: 0.6, ease: "power2.inOut" }, t);

const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa
const sceneDur = 4; // duração da cena em s (troque pela real)

// items = manchas e riscos (posição base no centro), mix-blend-mode: screen ou multiply
const fps = 12, r = rng(31);
for (let k = 0; k < sceneDur * fps; k++) items.forEach((d) => { const on = r() < 0.25; tl.set(d, { opacity: on ? 0.5 + r() * 0.4 : 0, x: (r() - 0.5) * 1000, y: (r() - 0.5) * 1800 }, t + k / fps); });

// items = 3 radial-gradients (âmbar, laranja, vermelho), mix-blend-mode: screen, fora da borda direita
tl.fromTo(items, { x: 400, scale: 0.8, opacity: 0 }, { x: 0, scale: 1.4, opacity: 0.9, duration: 0.45, ease: "power1.in", stagger: 0.06 }, t);
tl.fromTo(items, { opacity: 0.9 }, { opacity: 0, duration: 0.4, ease: "power2.out", stagger: 0.04, immediateRender: false }, t + 0.55);

// el = cópia do fundo com filter blur, recortada no formato do cartão; items = conteúdo do cartão
tl.fromTo(el, { clipPath: "inset(50% 10% 50% 10% round 40px)", filter: "blur(0px) brightness(1)" }, { clipPath: "inset(30% 10% 30% 10% round 40px)", filter: "blur(28px) brightness(1.15)", duration: 0.6, ease: "power3.out" }, t);
tl.fromTo(items, { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.4, ease: "power3.out", stagger: 0.06 }, t + 0.2);

// items = [núcleo, reflexo1, reflexo2, reflexo3]; mix-blend-mode: screen
const [core, ...ghosts] = items, factors = [-0.4, -0.8, -1.3];
tl.fromTo(core, { x: -400, opacity: 0 }, { x: 400, opacity: 1, duration: 1.2, ease: "sine.inOut" }, t);
ghosts.forEach((g, i) => tl.fromTo(g, { x: -400 * factors[i % 3], opacity: 0 }, { x: 400 * factors[i % 3], opacity: 0.5, duration: 1.2, ease: "sine.inOut" }, t));

// items = manchas de luz quente (radial-gradient, mix-blend-mode: screen), maiores que o quadro
tl.fromTo(items, { x: -500, opacity: 0 }, { x: 400, duration: 1.6, ease: "sine.inOut", stagger: 0.2 }, t);
tl.fromTo(items, { opacity: 0 }, { opacity: 0.5, duration: 0.8, ease: "sine.inOut", yoyo: true, repeat: 1, stagger: 0.2, immediateRender: false }, t);

// items = [card, <feDisplacementMap> do filtro do fundo atrás do card, faixa de brilho]
const [card, disp, shine] = items;
tl.fromTo(card, { scale: 0.85, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.6, ease: "back.out(1.6)" }, t);
tl.fromTo(disp, { attr: { scale: 80 } }, { attr: { scale: 18 }, duration: 0.8, ease: "elastic.out(1, 0.5)" }, t);
tl.fromTo(shine, { xPercent: -120, opacity: 0 }, { xPercent: 120, opacity: 0.7, duration: 0.9, ease: "power2.inOut" }, t + 0.2);

// items = [elemento, <feGaussianBlur> do filtro aplicado a ele]
const [node, blur] = items;
tl.fromTo(node, { x: -700 }, { x: 0, duration: 0.35, ease: "power4.out" }, t);
tl.fromTo(blur, { attr: { stdDeviation: "40 0" } }, { attr: { stdDeviation: "0 0" }, duration: 0.35, ease: "power4.out" }, t);

// el = texto com -webkit-text-stroke e filter: drop-shadow(0 0 18px #ff2fd1) fixos no CSS
const seq = [0, 1, 0, 0.3, 1, 0, 1, 0.6, 1];
seq.forEach((o, k) => tl.set(el, { opacity: o }, t + k * 0.05));

const sceneDur = 4; // duração da cena em s (troque pela real)

// el = textura de papel maior que o quadro, mix-blend-mode: multiply
const poses = [{ x: 0, y: 0, rotation: 0 }, { x: 6, y: -4, rotation: 0.3 }, { x: -5, y: 3, rotation: -0.2 }];
tl.set(el, { opacity: 0.5 }, t);
for (let k = 0; k < sceneDur * 6; k++) tl.set(el, poses[k % poses.length], t + k / 6);

const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa

// items = colunas verticais da imagem (clones recortados por clip-path)
const r = rng(5), amt = items.map(() => 1 + r() * 0.8);
items.forEach((c, i) => tl.fromTo(c, { scaleY: 1, transformOrigin: "50% 0%" }, { scaleY: amt[i], duration: 0.4, ease: "power2.in" }, t));
tl.fromTo(items, { scaleY: (i) => amt[i] }, { scaleY: 1, duration: 0.3, ease: "power3.out", immediateRender: false }, t + 0.5);

// items = [feFuncR, feFuncG, feFuncB] (type="discrete") do <filter id="poster">; el = foto com filter: url(#poster)
const tables = ["0 1", "0 0.5 1", "0 0.33 0.67 1", "0 0.25 0.5 0.75 1"];
tl.set(el, { filter: "url(#poster)" }, t);
tables.forEach((v, k) => tl.set(items, { attr: { tableValues: v } }, t + k * 0.12));
tl.set(el, { filter: "none" }, t + tables.length * 0.12);

// items = [cópia vermelha, cópia ciano] sobre o original, mix-blend-mode: screen
const [red, cyan] = items;
const offs = [0, 14, -8, 18, 6, 10, 0]; // px, valores fixos
tl.set([red, cyan], { opacity: 0.8 }, t);
offs.forEach((d, k) => { tl.set(red, { x: -d }, t + k * 0.05); tl.set(cyan, { x: d }, t + k * 0.05); });
tl.set([red, cyan], { opacity: 0 }, t + offs.length * 0.05);

const sceneDur = 4; // duração da cena em s (troque pela real)

// el = camada com repeating-linear-gradient (linhas de 4 px), maior que o quadro
tl.set(el, { opacity: 0.18 }, t);
tl.fromTo(el, { y: 0 }, { y: 8, duration: 0.5, ease: "none", repeat: Math.floor(sceneDur / 0.5) - 1 }, t);

tl.fromTo(el, { x: -300 }, { x: 0, duration: 1, ease: "steps(12)" }, t);
const jit = [-1.5, 1, -0.5, 1.2, -1, 0.6]; // graus por quadro
for (let k = 0; k < 12; k++) tl.set(el, { rotation: jit[k % jit.length] }, t + k / 12);

const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa

// el = camada de ruído sobre o elemento (overflow: hidden no pai)
const r = rng(57), frames = 9; // 0,3 s a 30 fps
for (let k = 0; k < frames; k++) tl.set(el, { opacity: 0.85 - (k / frames) * 0.3, x: (r() - 0.5) * 200, y: (r() - 0.5) * 200 }, t + k / 30);
tl.set(el, { opacity: 0 }, t + frames / 30);

const rng = (s) => () => ((s = (s * 16807) % 2147483647) / 2147483647); // pseudoaleatório com seed fixa
const sceneDur = 4; // duração da cena em s (troque pela real)

// items = faixas horizontais (clones recortados por clip-path); el = barra de tracking
const step = 1 / 15, r = rng(7);
for (let k = 0; k < sceneDur / step; k++) items.forEach((s) => tl.set(s, { x: r() < 0.15 ? (r() - 0.5) * 60 : 0 }, t + k * step));
tl.fromTo(el, { yPercent: -100 }, { yPercent: 1900, duration: 2.5, ease: "none", repeat: Math.max(0, Math.floor(sceneDur / 2.5) - 1) }, t);

// el = camada radial-gradient(transparent 50%, rgba(0,0,0,0.85)) cobrindo a tela
tl.fromTo(el, { opacity: 0.35, scale: 1.15 }, { opacity: 0.75, scale: 1, duration: 0.2, ease: "power2.out" }, t);
tl.fromTo(el, { opacity: 0.75, scale: 1 }, { opacity: 0.35, scale: 1.15, duration: 0.6, ease: "power2.inOut", immediateRender: false }, t + 0.2);
